import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`thumbtack-audit`,heroTitle:`Audit your Thumbtack profile in minutes`,heroSubtitle:`Perplexity Computer audits your Thumbtack profile, pricing, and lead-conversion flow, then shows exactly what to fix to win more jobs.`,inputUrlCta:`Audit my profile`,inputUrlPlaceholder:`thumbtack.com/profile/your-profile`,inputUrlPrefill:`Go to {url} and run a full Thumbtack profile audit. 1) Review the headline, bio, services, pricing, photos, reviews, and lead-response setup. 2) Analyze how clearly the profile explains what you do, what makes you different, and why a customer should contact you. 3) Benchmark against top Thumbtack pros in the same categories for positioning, pricing, and trust cues. 4) Recommend the highest-impact fixes for profile copy, price presentation, and lead conversion. 5) Deliver a prioritized action plan with rewritten copy and booking recommendations.`,heroOverlaySteps:[`Reviewing your Thumbtack profile, pricing, reviews, and lead-response setup`,`Benchmarking strong local pros for category positioning and trust cues`,`Rewriting your profile and prioritizing the fixes most likely to increase leads`,`Profile audit, pricing guidance, and booking recommendations ready to use`],generatingSteps:[`Visiting {url} to review your Thumbtack profile, services, and pricing`,`Designing an agent to benchmark nearby pros in the same categories`,`Configuring copy rewrites, rate guidance, and lead-conversion improvements`,`Setting up an action plan with ready-to-use edits and next steps`],featureSectionTitle:`From profile traffic to more qualified leads`,featureCardTitles:[`Connects to your lead-gen stack`,`Fixes you can apply today`],featureCardDescriptions:[`Computer breaks your Thumbtack audit into profile review, pricing research, trust-signal analysis, and messaging rewrites, then routes each step to the right model.`,`Thumbtack, Docs, Sheets, and planning tools can all feed one workflow so profile edits and follow-up guidance stay organized.`,`Profile rewrites. Rate guidance. Better trust cues. Lead-conversion recommendations. Computer gives you updates tied directly to more jobs won.`],capabilitySectionTitle:`Your profile optimizer, on autopilot`,capabilitySectionSubtitle:`Paste your Thumbtack profile, step away, and come back to a clearer plan to win more leads.`,capabilityCards:[{title:`Profile Audit`,description:`Computer can review your bio, services, pricing, reviews, and photos to find the friction hurting quote requests and bookings.`},{title:`Category Benchmarking`,description:`Computer can compare your positioning and rates with strong nearby pros so the gaps are obvious and actionable.`},{title:`Copy Improvements`,description:`Computer can rewrite your headline, services, and CTA language so customers understand why they should contact you now.`},{title:`Connect Your Tools`,description:`Computer can organize research, drafts, and next steps across Thumbtack, Docs, Sheets, and planning tools so updates are easy to ship.`},{title:`Remember Your Services`,description:`Computer can remember your categories, preferred jobs, and positioning so future audits start with the right context.`},{title:`Watch Conversion Signals`,description:`Computer can revisit your profile over time, flag when positioning drifts, and suggest the next change most likely to improve lead flow.`}]});export{t as default};
